import{j as i}from"./visuals-Ce7GuSSc.js";import{CoachPage as o}from"./AnalyzeCoach-BJXegv5Z.js";import"./icons-CCIdVrYy.js";import"./index-D7tppf-9.js";import"./solvedBank-BANsIFAb.js";import"./mockBlueprint-GBgEdbNo.js";import"./MathMD-BDnf3D6W.js";import"./Markdown-C6bccIV2.js";import"./SolvedBank-DQdscXq-.js";import"./MinitabFigure-Dv3p2-NV.js";const r=[22,28,31,35,40,44,48,53,57,61,66,70],l=[18.2,19.5,21.4,20.8,23.9,24.1,26.7,27,29.8,29.1,32.6,33.4],a=r.map((e,t)=>[e,l[t]]),c=[17.75,19.68,20.64,21.93,23.53,24.82,26.1,27.71,28.99,30.28,31.89,33.17],d=[.45,-.18,.76,-1.13,.37,-.72,.6,-.71,.81,-1.18,.71,.23],h=[[0,9],[2,6.1],[4,4.2],[6,3.6],[8,4],[10,5.9],[12,8.8]],u=[30,35,40,45,50,55,60,65,70,75,80,85],f=[13.3,11.6,12.8,12.8,15.2,15.2,18.4,21.7,23.4,28.5,32.1,38.1],m=u.map((e,t)=>[e,f[t]]),p=[5.41,1.46,.41,-1.84,-1.69,-3.93,-2.98,-1.93,-2.48,.37,1.73,5.48],g=[7.89,10.14,12.39,14.64,16.89,19.13,21.38,23.63,25.88,28.13,30.37,32.62],b=[4,6,8,10,12,15,18,20,22,25,28,32,35,40],v=[4.7,4.6,6.2,6.1,7,7,9.5,9.3,9.5,11.1,10.7,12.8,14.2,15],y=b.map((e,t)=>[e,v[t]]),w=[[4,3.966,5.033],[8,5.235,6.127],[12,6.491,7.235],[16,7.724,8.366],[20,8.923,9.531],[24,10.081,10.737],[28,11.207,11.975],[32,12.312,13.234],[36,13.404,14.505],[40,14.49,15.783]],k=[[4,3.242,5.756],[8,4.459,6.904],[12,5.666,8.061],[16,6.862,9.228],[20,8.049,10.405],[24,9.224,11.593],[28,10.39,12.792],[32,11.545,14.001],[36,12.69,15.219],[40,13.827,16.446]],A=[.337,-.233,.332,-.523,-.092,.499,-.357,-.057,-.699,.028,.193,-.243,1.795,-.45,.206,-.429,-.047,-.425,.275,-.111],C=[1.96,3.33,3.87,.92,4.89,3.3,2.06,5.76,4.2,2.37,.91,5.44,3.51,2.75,3.99,4.53,1.95,2.03,4.32,8.81],I=[-2,-1.75,-1.5,-1.25,-1,-.75,-.5,-.25,0,.25,.5,.75,1,1.25,1.5,1.75,2],R=[1.85,1.669,1.522,1.405,1.313,1.244,1.196,1.168,1.159,1.168,1.198,1.247,1.319,1.417,1.544,1.704,1.906],T=[{topic:"4.1.1",title:"Correlation",oneLine:"Correlation, r, is one number from −1 to +1 that tells you how strongly two continuous variables move together in a straight line, but it never proves cause.",explain:["Improve starts with a simple question: **when X changes, does Y change with it?** Correlation answers it with one number, **Pearson r**. Both X and Y must be **continuous**, measured on the same items (the book calls this **bivariate** data).","Always **plot first**. Put X on the horizontal axis and Y on the vertical axis. Read the scatter plot for **direction** (up or down), **form** (straight, curved, no pattern) and **strength** (tight or loose).","The formula: $$r=\\dfrac{S_{xy}}{\\sqrt{S_{xx}\\,S_{yy}}}$$ r is always between **−1 and +1**. The **sign** is the direction. The **size** is the strength. r = −0.95 is just as strong as r = +0.95. The book’s rule of thumb: |r| above 0.80 is practically strong, below 0.20 is weak.","Square r to get **R²**, the share of Y’s variation that goes with the straight line. r = 0.9 → R² = 0.81 → 81%. R² loses the sign.","Three limits. r only sees **straight lines**: a strong U-shape can give r ≈ 0. One **outlier** can create or destroy r. And correlation is **not causation**: a lurking variable (such as region size) can drive both X and Y."],example:`**Link utilisation vs latency (12 links).** A NOC engineer records busy-hour utilisation (%) and latency (ms) on 12 links.

- The scatter plot rises in a tight, straight cigar shape.
- Minitab: **r = 0.989**, p < 0.001. Strong, positive, significant.
- R² = 0.989² = **0.978** → about 97.8% of the variation in latency goes with utilisation.

**Is it significant?** H₀: ρ = 0. $$t=\\dfrac{r\\sqrt{n-2}}{\\sqrt{1-r^2}}=\\dfrac{0.989\\sqrt{10}}{\\sqrt{1-0.978}}\\approx 21.1$$ with df = n − 2 = 10. Far beyond 2.228, so reject H₀.

**Hand calculation.** Five installs: $S_{xy}=69$, $S_{xx}=10$, $S_{yy}=490$. $$r=\\dfrac{69}{\\sqrt{10\\times 490}}=\\dfrac{69}{70}=0.986$$`,readIt:["Look at the scatter plot first: direction, form, strength.","Sign of r = direction. Size of |r| = strength. Compare **absolute** values to find the strongest.","p-value of the correlation < 0.05 → reject H₀: ρ = 0 → the correlation is significant.","R² = r² gives the % of variation in Y that goes with X.","r near 0 → no **linear** relationship. Check the plot for a curve."],remember:["r runs from −1 to +1; 0 = no linear relationship.","r = Sxy ÷ √(Sxx·Syy); no units.","R² = r² (r = 0.7 → R² = 49%).","Test H₀: ρ = 0 with t = r√(n−2)/√(1−r²), df = n − 2.","Book rule of thumb: |r| > 0.80 strong, |r| < 0.20 weak.","Correlation does not prove causation."],traps:["r = −0.92 is stronger than r = +0.85. The minus sign is direction, not weakness.","r = 0.7 does not mean 70% explained. R² = 0.49, so 49%.",'r ≈ 0 does not mean "no relationship". It means no straight-line relationship; a curve can hide.',"Degrees of freedom for the correlation test are n − 2, not n − 1."],video:[{kind:"title",say:"Correlation: does Y move when X moves, and how strongly?",title:"Correlation",sub:"One number from −1 to +1"},{kind:"figure",say:"Twelve links. As utilisation goes up, latency goes up in a tight straight line. r = 0.989: strong and positive.",title:"A strong positive correlation",figure:{kind:"scatter",title:"Scatterplot of Latency vs Utilisation",points:a,xLabel:"Utilisation (%)",yLabel:"Latency (ms)",stats:[["r","0.989"],["R²","97.8%"],["P-Value","0.000"]]},callouts:["Rises left to right → positive","Tight straight cigar → strong","r = 0.989, R² = 97.8%"]},{kind:"bullets",say:"Read r in two parts: the sign gives the direction, the size gives the strength. Square it to get R².",title:"Reading r",bullets:["Sign: + rises, − falls","Size: |r| near 1 = strong, near 0 = weak","−0.95 is as strong as +0.95","R² = r²: r = 0.9 → 81%"]},{kind:"figure",say:"Careful. Antenna tilt and drop rate make a clear U-shape, yet r = −0.04. r only sees straight lines.",title:"r ≈ 0 can hide a curve",figure:{kind:"scatter",title:"Scatterplot of Drop Rate vs Antenna Tilt",points:h,xLabel:"Tilt (degrees)",yLabel:"Drop rate (%)",stats:[["r","−0.04"],["P-Value","0.930"]]},callouts:["Strong U-shaped pattern","But r = −0.04","Always plot before you trust r"]},{kind:"formula",say:"To test if r is significant, use t with n minus 2 degrees of freedom. If p is below alpha, reject H0: rho equals zero.",title:"Is r significant?",name:"t",num:"r × √(n − 2)",den:"√(1 − r²)",note:"df = n − 2 · p < α → reject $H_0: \\rho = 0$"},{kind:"callout",say:"Remember: correlation shows association, never cause. A lurking variable can drive both.",big:"Correlation ≠ causation",small:"Plot first · sign = direction · R² = r²"}]},{topic:"4.1.2",title:"Regression Equations",oneLine:"Simple linear regression fits the best straight line Ŷ = b₀ + b₁X through the data, so you can predict Y from X inside the range you studied.",explain:["Correlation says *how strong*. Regression gives the **equation**: $$\\hat{Y}=b_0+b_1X$$ **b₀** is the **intercept** (Y when X = 0). **b₁** is the **slope**: the change in Y for **one unit** of X.","**Least squares** picks the line that makes the **sum of squared residuals** as small as possible. The line always passes through the point $(\\bar{x},\\bar{y})$. By hand: $$b_1=\\dfrac{S_{xy}}{S_{xx}}\\qquad b_0=\\bar{y}-b_1\\bar{x}$$","Minitab gives three fit numbers. **R²** = SSR ÷ SST, the share of variation explained. **R²(adj)** adjusts for the number of terms. **S** = √MSE, the typical size of a prediction error, in Y units.","Is X useful? Look at the **p-value of the slope** (or the ANOVA F). p < α → the slope is not zero → X helps predict Y. In simple regression F = T² and both give the same p-value. Ignore the constant’s p-value for this question.","Predict **only inside the X range** you studied. Outside it is **extrapolation**, and the line may be badly wrong."],example:`**Latency model (12 links).** Minitab output:

Latency = **10.69 + 0.321 × Utilisation**, S = 0.787, R² = 97.8%, R²(adj) = 97.6%, slope p < 0.001.

- **Slope:** each extra 1 percentage point of utilisation adds about **0.32 ms**.
- **Prediction at 50%:** 10.69 + 0.321 × 50 = **26.75 ms**.
- **At 95%:** the line says 41.2 ms. But the data stop at 70%. In a wider data set the real value was 79.5 ms. That is extrapolation.

**Hand calculation (5 installs).** x̄ = 3, ȳ = 66, Sxy = 69, Sxx = 10:
$$b_1=\\dfrac{69}{10}=6.9\\qquad b_0=66-6.9\\times 3=45.3$$ so Ŷ = 45.3 + 6.9X.`,readIt:['Regression equation: the number next to X is the slope; read it with units ("ms per % point").',"Slope p-value < α → X is a significant predictor.","R-Sq = % of Y variation explained by the line. S = typical error in Y units.","Check the X range in the data before you predict."],remember:["Ŷ = b₀ + b₁X: b₀ intercept, b₁ slope.","b₁ = Sxy ÷ Sxx; b₀ = ȳ − b₁x̄.","The line passes through (x̄, ȳ).","R² = SSR ÷ SST; S = √MSE.","Simple regression: F = T², same p-value.","Least squares minimises the sum of squared residuals."],traps:["b₀ = ȳ − b₁ is wrong; it is ȳ − b₁x̄.","R² = SSE ÷ SST is the unexplained share, not R².","A high R² does not prove that X causes Y.",'Predicting far outside the data range is extrapolation; the best answer often says "cannot be reliably predicted".'],video:[{kind:"title",say:"Regression gives you the equation of the line, so you can predict Y from X.",title:"Regression Equations",sub:"Ŷ = b₀ + b₁X"},{kind:"figure",say:"The red line is the least squares fit. For every one percent more utilisation, latency rises by about 0.32 milliseconds.",title:"The fitted line",figure:{kind:"scatter",title:"Fitted Line Plot: Latency = 10.69 + 0.321 Util",points:a,xLabel:"Utilisation (%)",yLabel:"Latency (ms)",fit:{b0:10.686,b1:.3212},stats:[["S","0.787"],["R-Sq","97.8%"],["R-Sq(adj)","97.6%"]]},callouts:["Intercept b₀ = 10.69","Slope b₁ = 0.321 ms per % point","S = 0.787 ms typical error"]},{kind:"formula",say:"By hand, the slope is S x y divided by S x x. Then the intercept is y bar minus slope times x bar.",title:"The slope by hand",name:"b₁",num:"Sxy",den:"Sxx",note:"Then $b_0=\\bar{y}-b_1\\bar{x}$. The line passes through $(\\bar{x},\\bar{y})$."},{kind:"bullets",say:"Read three numbers: R² is the share explained, S is the typical error. The slope p-value tells you if X matters.",title:"Read the output",bullets:["R² = SSR ÷ SST: share explained","S = √MSE: typical error in Y units","Slope p < α → X is significant","Ignore the constant’s p-value"]},{kind:"decision",say:"Before you predict, ask: is X inside the range of the data? If not, the prediction is extrapolation and cannot be trusted.",title:"Can I predict here?",question:"Is the X value inside the range you studied?",yes:"Predict with the equation",no:"Extrapolation: unreliable"},{kind:"callout",say:"Remember: slope = Sxy over Sxx, and only predict inside the data.",big:"b₁ = Sxy ÷ Sxx, b₀ = ȳ − b₁x̄",small:"Never extrapolate"}]},{topic:"4.1.3",title:"Residuals Analysis",oneLine:"A residual is observed minus fitted; the four residual plots check that the errors are normal, have equal spread, are independent and show no pattern.",explain:["A **residual** is the part the line did not explain: $$e=y-\\hat{y}$$ **Observed minus fitted.** A positive residual means the point is above the line.","Regression is only valid if the residuals behave. Four assumptions: **normal** residuals, **equal variance** (constant spread), **independence** (no pattern over time), and the **right form** (a straight line fits).","Minitab’s **four-in-one** plot checks them. **Normal probability plot** and **histogram** → normality. **Versus fits** → equal variance and form. **Versus order** → independence (only useful if the data are in time order).","Know the bad shapes. **Funnel** in versus fits → unequal variance. **U or arch** in versus fits → wrong form (a curve). **Trend or cycle** in versus order → not independent.","Minitab flags points. **R** = large standardised residual (|value| > 2). **X** = high leverage (unusual X value). Investigate flagged points. Do not delete them just because they are flagged."],example:`**Latency model check.** Link at 35% utilisation: observed 20.8 ms, fitted 21.93 ms.

Residual = 20.8 − 21.93 = **−1.13 ms** (the point is below the line). Standardised residual −1.54: not flagged.

All 12 residuals lie between −1.18 and +0.81 ms. Normal plot is straight (AD p = 0.079 > 0.05). Versus fits shows a random band. **The model is healthy.**

**What a problem looks like.** If link 7 had been logged as 33.5 ms instead of 26.7 ms: residual 6.82, standardised residual **3.00 → flagged R**. R² drops from 97.8% to 83.3%. First step: check the data source, not delete the point.`,readIt:["Normal probability plot: points on the straight line → residuals normal.","Versus fits: random band around 0 → OK. Funnel → unequal variance. U-shape → curve missing.","Versus order: random → independent. Trend or cycles → time effect.","R = |standardised residual| > 2; X = high leverage. Investigate first."],remember:["Residual = observed − fitted.","Assumptions: normal, equal variance, independent, correct form.","Normality → normal plot / histogram.","Equal variance → versus fits (funnel = problem).","Independence → versus order.","Raw residuals always average zero."],traps:['Residual is not "predicted minus actual"; it is actual minus predicted.',"Equal variance is checked on versus fits, not on the normal plot.","A U-shape means the wrong form (curvature), not unequal variance.","A flagged R point must be investigated, not automatically removed."],video:[{kind:"title",say:"Residuals tell you if you can trust the regression line.",title:"Residuals Analysis",sub:"Observed minus fitted"},{kind:"callout",say:"A residual is the observed value minus the fitted value. Positive means the point is above the line.",big:"Residual = Observed − Fitted",small:"Link at 35%: 20.8 − 21.93 = −1.13 ms (below the line)"},{kind:"figure",say:"Here is a healthy four-in-one plot. Straight normal plot, random band versus fits, no pattern in time order.",title:"A healthy model",figure:{kind:"residuals",title:"Residual Plots for Latency",residuals:d,fits:c},callouts:["Normal plot: points on the line","Versus fits: random band","Versus order: no trend"]},{kind:"bullets",say:"Learn which plot checks which assumption. This is a favourite exam question.",title:"Which plot checks what?",bullets:["Normal plot + histogram → normality","Versus fits → equal variance and form","Versus order → independence","All four must look random"]},{kind:"compare",say:"Two bad shapes in versus fits. A funnel means the spread grows: unequal variance. A U-shape means a curve is missing.",title:"Bad shapes in versus fits",left:{head:"Funnel ◁",points:["Spread grows with fitted value","Unequal variance","Fix: transform Y"]},right:{head:"U or arch ∪",points:["Residuals curve","Wrong form","Fix: add X² term"]}},{kind:"callout",say:"Remember: R means a large residual, X means high leverage. Investigate before you delete.",big:"R = large residual · X = high leverage",small:"Investigate, don’t just delete"}]},{topic:"4.2.1",title:"Non-Linear Regression",oneLine:"When the data bend, add an X² term (quadratic) or X³ (cubic), and choose the simplest model with the best adjusted R² and a significant top term.",explain:["Many service processes **bend**. Latency is flat at low utilisation, then climbs fast as the link fills. A straight line misses this.","Signs of curvature: the scatter plot bends; residuals versus fits show a **U or arch**; points at the ends get flagged R.","Fix it with a **polynomial**. Quadratic: $$\\hat{Y}=b_0+b_1X+b_2X^2$$ bends once. **Cubic** adds X³ for an S-shape. Minitab: *Stat > Regression > Fitted Line Plot*, choose Quadratic or Cubic.","How to choose: **R² can never fall when you add a term**, so do not use R² alone. Compare **R²(adj)** and **S**, and check the **p-value of the highest-order term**. Keep the **simplest** model that works (parsimony).","Two rules. **Hierarchy:** if X² is in the model, keep X too. **No extrapolation:** curves that agree inside the data can disagree wildly outside it. Transforming X or Y (log, √) is another way to straighten a curve."],example:`**Latency vs utilisation, 30–85% (12 links).**

| Model | R² | R²(adj) | S |
|---|---|---|---|
| Linear | 87.30% | 86.03% | 3.24 |
| **Quadratic** | **99.46%** | **99.34%** | **0.71** |
| Cubic | 99.46% | 99.26% | 0.75 |

The quadratic is the winner: adj R² jumps and S drops by 4×. The cubic adds nothing (X³ p = 0.77; adj R² falls slightly, S rises).

Quadratic: Latency = 27.45 − 0.813U + 0.01098U².

**Extrapolation:** at 95% the linear says 37.1 ms and the quadratic says 49.3 ms. The data stop at 85%, so neither can be trusted.`,readIt:["U or arch in residuals versus fits → a curve is missing.","Compare models with R²(adj) and S, not R².","Highest-order term p > α → drop it and use the simpler model.","Big gap between R² and R²(adj) → terms that do not pull their weight."],remember:["Quadratic: Ŷ = b₀ + b₁X + b₂X² (one bend). Cubic adds X³.","R² never decreases when a term is added.","Choose by adj R², S and the top term’s p-value.","Hierarchy: keep X when X² is in the model.","Never extrapolate a polynomial.","Transform spec limits too if you transform Y."],traps:["Choosing the cubic because its R² is highest. Look at adj R² and S.","Dropping X but keeping X² breaks the hierarchy rule.","A good-fitting curve still shows association, not cause.","The best evidence a linear model is wrong is a curved residual pattern, not a modest R²."],video:[{kind:"title",say:"When the data bend, a straight line is the wrong model.",title:"Non-Linear Regression",sub:"Quadratic and cubic fits"},{kind:"figure",say:"Fit a straight line to curved data, and the residuals make a U-shape. High at both ends, low in the middle.",title:"The warning sign",figure:{kind:"residuals",title:"Residual Plots: Linear Model",residuals:p,fits:g},callouts:["Versus fits: U-shape","The straight line misses the curve","Add an X² term"]},{kind:"figure",say:"The quadratic follows the bend. R squared adjusted rises from 86 to 99 percent, and S falls from 3.24 to 0.71.",title:"The quadratic fits",figure:{kind:"scatter",title:"Fitted Line Plot: Quadratic",points:m,xLabel:"Utilisation (%)",yLabel:"Latency (ms)",fit:{b0:27.445,b1:-.81335,b2:.010982},stats:[["S","0.707"],["R-Sq","99.5%"],["R-Sq(adj)","99.3%"]]},callouts:["Ŷ = 27.45 − 0.813U + 0.011U²","adj R²: 86.0% → 99.3%","S: 3.24 → 0.71"]},{kind:"steps",say:"Compare adjusted R² and S, and check the p-value of the top term. Then keep the simplest model that works.",title:"Choose the model",steps:["Fit linear, quadratic, cubic","Compare adj R² and S","Top term p > α → drop it","Keep the simplest good model"]},{kind:"compare",say:"Two traps. R squared always rises with more terms. And curves go wild outside the data.",title:"Two traps",left:{head:"R² always rises",points:["Cubic R² ≥ quadratic R²","Use adj R² and S instead","Parsimony wins"]},right:{head:"No extrapolation",points:["Data stop at 85%","At 95%: 37 ms vs 49 ms","Neither can be trusted"]}},{kind:"callout",say:"Remember: keep X when X squared is in, and choose with adjusted R squared.",big:"Choose by adj R² and S, not R²",small:"Hierarchy: keep X when X² stays"}]},{topic:"4.2.2",title:"Multiple Linear Regression",oneLine:"Multiple regression models Y with two or more X’s at once; each coefficient is the change in Y per unit of that X with the other X’s held constant.",explain:["Real outputs have several drivers. **Multiple linear regression (MLR)** fits $$\\hat{Y}=b_0+b_1X_1+b_2X_2+\\dots+b_kX_k$$ Each **bⱼ** is the change in Y for one unit of Xⱼ **with the other X’s held constant**.","Two kinds of test. The **overall F-test** asks: is the model useful at all? Each **t-test** (p-value per coefficient) asks: does this X help, given the others? Both use error df = n − k − 1.","**R² never falls when you add an X**, even a useless one. So compare models with **R²(adj)** and **S**. Remove the term with the **highest p-value above α** first, one at a time, then refit.","**Multicollinearity** = the X’s are correlated with each other. Symptoms: significant F but weak t-tests, big standard errors, coefficients that flip sign. Measure it with $$VIF=\\dfrac{1}{1-R_j^2}$$ VIF = 1 is perfect. Above 5 is a concern. Above 10 is serious.","MLR on **historical data** shows association, not cause. The book says it is **not** a form of experimentation. Confirm key X’s with a pilot or a DOE."],example:`**MTTR model (20 weeks).** Y = mean time to restore (h); X’s = Backlog (B), Staff on shift (S), Knowledge-base accuracy % (A).

MTTR = **5.418 + 0.02235 B − 0.2695 S − 0.0414 A**

All p-values < 0.001; R² = 91.5%, R²(adj) = 89.9%, S = 0.293 h; VIFs 1.23, 1.06, 1.19 (no collinearity).

- **One more engineer**, same backlog and accuracy → MTTR falls by **0.27 h**.
- **Predict** (B 180, S 8, A 75): 5.418 + 0.02235×180 − 0.2695×8 − 0.0414×75 = **4.18 h**. With 10 staff: **3.64 h**.

**Junk test:** adding "day of month" raised R² (91.5 → 92.0%) but **lowered** adj R² (89.9 → 89.8%), p = 0.36. Drop it.

**Collinearity test:** adding "aged tickets" (r = 0.98 with backlog) pushed VIF to 34 and backlog’s p to 0.084.`,readIt:["Overall: ANOVA F p-value < α → the model is useful.","Each X: coefficient p-value < α → it helps, given the others.","Compare models with R²(adj) and S. Remove the highest p first, then refit.","VIF > 5 (serious > 10) → the X’s overlap; drop or combine one."],remember:["Ŷ = b₀ + b₁X₁ + … + bₖXₖ.","bⱼ = change in Y per unit Xⱼ, other X’s held constant.","Error df = n − k − 1.","R² never falls when you add an X; use adj R².","VIF = 1 ÷ (1 − Rⱼ²); > 5 concern, > 10 serious.","MLR is not an experiment: association only."],traps:["Choosing the model with the highest R² instead of the highest adj R².","A high VIF does not mean a strong effect on Y; it means an unstable coefficient.",'"p > 0.05 so X has no effect" — you only fail to reject; collinearity may hide it.',"Ranking X’s by coefficient size ignores their different units."],video:[{kind:"title",say:"Multiple regression: several X’s in one model.",title:"Multiple Linear Regression",sub:"Ŷ = b₀ + b₁X₁ + b₂X₂ + …"},{kind:"bullets",say:"Here is the MTTR model. Each coefficient is the effect of one X with the other X’s held constant.",title:"The MTTR model",bullets:["MTTR = 5.418 + 0.02235 B − 0.2695 S − 0.0414 A","+1 engineer → −0.27 h (B and A held constant)","R² 91.5%, adj R² 89.9%, S 0.293 h","Predict (180, 8, 75) → 4.18 h"]},{kind:"compare",say:"Two tests. The F-test checks the whole model. The t-tests check each X, given the others.",title:"Two kinds of test",left:{head:"Overall F-test",points:["Is the model useful at all?","One p-value in ANOVA","p < α → yes"]},right:{head:"Coefficient t-tests",points:["Does this X help, given the others?","One p-value per X","Remove highest p first"]}},{kind:"decision",say:"R squared always goes up when you add an X. So ask: did adjusted R squared go up too? If not, drop the new X.",title:"Keep the new X?",question:"Did adj R² rise (and S fall) when you added the X?",yes:"Keep it (if its p < α)",no:"Drop it: junk term"},{kind:"formula",say:"Multicollinearity is measured with VIF. One means no overlap. Above five is a concern, above ten is serious.",title:"Multicollinearity",name:"VIF",num:"1",den:"1 − Rⱼ²",note:"VIF 1 = fine · > 5 concern · > 10 serious. Aged tickets added → VIF 34."},{kind:"callout",say:"Remember: other X’s held constant, and use adjusted R squared to compare.",big:"bⱼ = effect with the other X’s held constant",small:"Compare with adj R² · VIF > 5 = trouble"}]},{topic:"4.2.3",title:"Confidence & Prediction Intervals",oneLine:"The confidence interval says where the average Y will be at a given X; the prediction interval says where one new Y will fall, so it is always wider.",explain:["A regression prediction is one number. But it has uncertainty. Minitab gives two intervals around it.",'The **confidence interval (CI)** is for the **mean** Y at that X. Use it for questions about averages ("what is the average install time for 30 km routes?").','The **prediction interval (PI)** is for **one new** observation. Use it for promises about a single unit ("how long will *this* 30 km route take?"). It adds the scatter of single points, so the **PI is always wider** than the CI.',"Both bands are **narrowest at x̄** and flare out towards the ends of the data. From Minitab output: CI = Fit ± t × SE Fit. PI = Fit ± t × √(S² + SE Fit²). Use df = n − 2 in simple regression.","More data shrinks the CI towards zero. The PI cannot shrink below about ±t × S. And never trust either interval outside the data range."],example:`**Fibre install time vs route length (14 routes).** Hours = 3.317 + 0.2955 × km, S = 0.522, df = 12, t = 2.179.

At **30 km**: Fit = 3.317 + 0.2955 × 30 = **12.18 h**.

- 95% **CI**: 11.76 to 12.60 h → the **average** 30 km route.
- 95% **PI**: 10.97 to 13.40 h → **one** new 30 km route.

At x̄ = 19.6 km the CI is only 0.61 h wide (the narrowest point). At 60 km the model says 21.0 h, but the data stop at 40 km: extrapolation.

**From SE Fit:** PI half-width = t × √(S² + SE Fit²) = 2.179 × √(0.522² + 0.193²) = **1.21 h**.`,readIt:["Question about the **average** → CI. About **one** unit or the **next** case → PI.","Inner bands = CI, outer bands = PI.","Bands are narrowest at x̄.","Fit ± t·SE Fit = CI. Fit ± t·√(S² + SE Fit²) = PI."],remember:["CI = mean response; PI = single new value.","PI is always wider than CI.","Both are narrowest at x̄.","df = n − 2 for simple regression.","CI shrinks with more data; PI levels off at about ±t·S.","Valid only inside the data range and if residuals are OK."],traps:["Using the CI to promise one customer’s install time — that needs the PI.",'"PIs are narrower than CIs" is false.',"Bands are not narrowest at the smallest X; they are narrowest at x̄.","Fit ± t·SE Fit is the CI, not the PI."],video:[{kind:"title",say:"Two intervals around a prediction: one for the average, one for a single value.",title:"Confidence & Prediction Intervals",sub:"Mean vs one new value"},{kind:"figure",say:"Red dashes are the confidence interval for the mean. Green dashes are the prediction interval for one route. The green band is wider.",title:"Two bands",figure:{kind:"scatter",title:"Fitted Line Plot: Hours = 3.317 + 0.2955 km",points:y,xLabel:"Route length (km)",yLabel:"Install time (h)",fit:{b0:3.3174,b1:.29548},ci:w,pi:k},callouts:["Inner (red) = 95% CI for the mean","Outer (green) = 95% PI for one route","Both narrowest near x̄ = 19.6 km"]},{kind:"compare",say:"At 30 kilometres the fit is 12.18 hours. The average route: 11.76 to 12.60. One route: 10.97 to 13.40.",title:"At 30 km",left:{head:"CI: the average route",points:["11.76 to 12.60 h","Width 0.84 h","For decisions about averages"]},right:{head:"PI: one new route",points:["10.97 to 13.40 h","Width 2.43 h","For promises to one customer"]}},{kind:"bullets",say:"From Minitab output, the confidence interval uses SE Fit only. The prediction interval adds S squared under the root, which is why it is wider.",title:"Intervals from the output",bullets:["CI = Fit ± t × SE Fit","PI = Fit ± t × √(S² + SE Fit²)","df = n − 2 (simple regression)","Example: 2.179 × √(0.522² + 0.193²) = 1.21 h"]},{kind:"decision",say:"Ask one question. Is it about one unit, or the average? One unit means the prediction interval.",title:"Which interval?",question:"Is the question about ONE new unit?",yes:"Prediction interval (wider)",no:"Mean response → confidence interval"},{kind:"callout",say:"Remember: the prediction interval is always wider, and both are narrowest at x bar.",big:"PI is always wider than CI",small:"Both narrowest at x̄"}]},{topic:"4.2.4",title:"Residuals Analysis (Multiple Regression)",oneLine:"Multiple regression uses the same residual checks as simple regression, plus residuals versus each X, leverage and influence, and VIF for collinearity.",explain:["The residual assumptions do not change: **normal**, **constant variance**, **independent**. Use the same four-in-one plot.","Multiple regression **adds** checks. Plot residuals **versus each X** to find a missing curve in one X. Check **leverage**, **influence** and **multicollinearity**.","Minitab flags: **R** = |standardised residual| > 2 (an unusual Y). **X** = leverage above 3p/n (an unusual combination of X’s; p = number of coefficients incl. the constant).","**Cook’s distance** combines residual and leverage to measure **influence**: how much the coefficients move if you drop the point. Above 1 is clearly influential. **Durbin-Watson** checks time order: about 2 = fine, well below 2 = runs (positive autocorrelation).","What to do: **investigate** each flagged point first (data error? special cause?). Delete only proven errors. Report results with and without. After any fix, **refit and re-check** every plot."],example:`**P2 incident MTTR (20 incidents).** MTTR = 1.822 + 0.1102 Backlog − 0.2363 Tenure; S = 0.566 h; R² 92.4%.

- **Obs 13:** observed 5.3 h, fit 3.51 h, residual 1.80, **St Resid 3.27 → R**. Normality fails with it (AD p = 0.025). Without it AD p = 0.646. Investigate: was it a special cause?
- **Obs 20:** backlog 72 (all others ≤ 40). Leverage **0.815 > 3p/n = 3×3/20 = 0.45 → X**. Its residual is small (−0.11), but Cook’s D = 0.31: it pulls the line.
- **VIF:** 1.28 for both X’s — fine. Adding a third X with r = 0.98 to backlog pushed VIF to 27.`,readIt:["R beside an observation = large standardised residual (|value| > 2).","X beside an observation = high leverage (> 3p/n).","Funnel in versus fits = unequal variance; curve in versus one X = that X needs a curved term.","Durbin-Watson ≈ 2 → independent; well below 2 → positive autocorrelation."],remember:["Same assumptions: normal, constant variance, independent.","Extra checks: versus each X, leverage, Cook’s D, VIF.","R = |St Resid| > 2; X = leverage > 3p/n.","Cook’s D > 1 = clearly influential.","Durbin-Watson ≈ 2 = no autocorrelation.","Investigate first; delete only proven errors."],traps:['"X" in Minitab means high leverage, not a large residual.',"VIF = 1 means no collinearity, not perfect collinearity.","A funnel shape is unequal variance, not multicollinearity.","The FIRST action for a flagged point is to investigate it, not delete it."],video:[{kind:"title",say:"Residual checks for multiple regression: the same plots, plus a few more.",title:"Residuals in Multiple Regression",sub:"Same assumptions, extra checks"},{kind:"figure",say:"One point stands out. Observation 13 has a residual of 1.8 hours. Its standardised residual is 3.27, so Minitab flags it R.",title:"Spot the problem",figure:{kind:"residuals",title:"Residual Plots for P2 MTTR",residuals:A,fits:C},callouts:["Obs 13: residual +1.80 → St Resid 3.27 (R)","Pulls the normal plot off the line","Obs 20 sits far right: fit 8.81"]},{kind:"compare",say:"R means the Y value is unusual; X means the X values are unusual. A point flagged with both is likely influential.",title:"R vs X",left:{head:"R: large residual",points:["|St Resid| > 2","Y is far from the fit","Obs 13: 3.27"]},right:{head:"X: high leverage",points:["Leverage > 3p/n","Unusual X values","Obs 20: 0.815 > 0.45"]}},{kind:"bullets",say:"Multiple regression adds four checks to the usual residual plots.",title:"Extra checks",bullets:["Residuals versus each X","Cook’s D: > 1 clearly influential","Durbin-Watson: ≈ 2 is good","VIF: > 5 concern, > 10 serious"]},{kind:"steps",say:"When a point is flagged, investigate first. Delete only a proven error. Then refit and check again.",title:"Flagged point? Do this",steps:["Investigate the source","Delete only proven errors","Report with and without","Refit and re-check plots"]},{kind:"callout",say:"Remember: R is a large residual, X is high leverage, and you always investigate first.",big:"R = unusual Y · X = unusual X’s",small:"Investigate first, then refit"}]},{topic:"4.2.5",title:"Data Transformation, Box-Cox",oneLine:"Box-Cox finds a power λ that makes skewed, positive data close to normal; λ = 1 means no change, 0.5 square root, 0 natural log, −1 reciprocal.",explain:["Service data are often **skewed**: most tickets close fast, a few take very long. Normal-based tools (capability, t-tests, control limits) can then mislead. A **transformation** can fix non-normality, unequal variance or a curve.","**First** look for a reason: a mix of two processes, outliers, special causes, or poor measurement resolution. Transform only after that.","**Box-Cox** raises the data to a power **λ (lambda)**. Learn the table: **λ = 1** no transformation · **0.5** square root · **0** natural log · **−0.5** 1/√Y · **−1** reciprocal 1/Y.","Minitab finds the λ that gives the **smallest standard deviation** of the standardised data. Use a **rounded λ** inside the confidence interval. **If the interval contains 1, no transform is needed.** Box-Cox needs **positive data**: add a constant first if there are zeros.","**Transform the spec limits too**, with the same function. A negative λ (reciprocal) reverses the order, so USL and LSL swap. Back-transform the endpoints of intervals, not the margins."],example:`**P2 MTTR, 30 incidents (hours).** Skewed right; AD p = 0.043 → not normal.

Box-Cox: **λ̂ = −0.003**, 95% CI **−0.71 to 0.70**, rounded **λ = 0 → ln(Y)**. After ln: AD p = **0.797** → normal.

**Spec:** USL = 8 h → transformed USL = ln 8 = **2.079**.

**Why it matters:** treating raw data as normal gave Ppk = 1.36 (about 21 ppm). On the ln scale Ppk = **0.83** (about 6,657 ppm). The raw answer was badly optimistic.

**Quick spec checks:** λ = 0.5, USL 100 → √100 = **10**. λ = −1: 1/8 = 0.125 and 1/0.5 = 2 → the order reverses.`,readIt:["Box-Cox plot: the curve’s lowest point is the best λ (Estimate).","Use the Rounded Value, which sits inside the lower and upper CL.","CI includes 1 → no transformation needed.","Check normality again after transforming (AD p > 0.05)."],remember:["λ = 1 none · 0.5 √Y · 0 ln Y · −0.5 1/√Y · −1 1/Y.","Best λ minimises the StDev of the standardised data.","CI contains 1 → no transform needed.","Data must be positive (shift zeros first).","Transform the spec limits with the same function.","Look for a cause of non-normality before transforming."],traps:['λ = 1 does not mean "log"; it means no transformation. λ = 0 is the log.',"Transforming the data but not the spec limits is wrong.","With a negative λ, the transformed USL can be smaller than the transformed LSL.","Box-Cox cannot be applied directly to data with zeros or negatives."],video:[{kind:"title",say:"Box-Cox: a power that turns skewed data into near-normal data.",title:"Box-Cox Transformation",sub:"Pick the power λ"},{kind:"bullets",say:"Learn the lambda table by heart. One means no change, zero means natural log.",title:"The λ table",bullets:["λ = 1 → no transformation","λ = 0.5 → √Y   ·   λ = 0 → ln Y","λ = −0.5 → 1/√Y","λ = −1 → 1/Y (order reverses)"]},{kind:"figure",say:"The curve is lowest near lambda zero. The confidence interval runs from minus 0.71 to 0.70 and does not contain one. So use the natural log.",title:"Reading the Box-Cox plot",figure:{kind:"boxcox",title:"Box-Cox Plot of P2 MTTR",lambdas:I,stdevs:R,best:0,lo:-.712,hi:.699,rounded:0},callouts:["Lowest StDev at λ ≈ 0 (−0.003)","CI −0.71 to 0.70: 1 is outside","Rounded λ = 0 → ln(Y)"]},{kind:"compare",say:"After the log transform the data pass the normality test, and the real capability is much lower.",title:"Before and after",left:{head:"Raw hours",points:["AD p = 0.043 (not normal)","Ppk = 1.36 (too optimistic)"]},right:{head:"ln(hours)",points:["AD p = 0.797 (normal)","USL 8 → ln 8 = 2.079","Ppk = 0.83"]}},{kind:"steps",say:"The safe order: look for a cause, check the data are positive, transform data and specs, then check normality again.",title:"Transform safely",steps:["Look for a cause first","Data positive? (shift zeros)","Transform data AND specs","Re-check normality"]},{kind:"callout",say:"Remember: lambda one is no change, lambda zero is the log, and specs are transformed too.",big:"λ 1 = none · 0.5 = √ · 0 = ln · −1 = 1/Y",small:"Transform the spec limits too"}]}],B=[{topic:"4.3.1",title:"Experiment Objectives",oneLine:"A designed experiment sets the X’s on purpose to prove cause and effect; its objective is screening, characterising, optimising or making the process robust.",explain:["Analyze narrowed many inputs to a **critical few**. Regression on historical data showed **association**. A **designed experiment (DOE)** changes the X’s **on purpose**, in a planned pattern, so it can show **cause and effect** and find **interactions**.","The book defines DOE as a scientific method of planning and running an experiment that yields the true cause-and-effect relationship between the X’s and the Y. The goal: the information you need **at minimum cost**.","Four objectives. **Screening:** which of many X’s matter? **Characterising:** how big are the effects, and do they interact? **Optimising:** what settings give the best Y (maximum, minimum or on target)? **Robustness:** how do we make Y insensitive to **noise** we cannot control? The book also lists **problem solving** (remove defects, cut cycle time).","Each objective has a typical design. Screening → **fractional factorial** (book: 4–15 factors). Characterising → **full factorial** (2–5 factors) + centre points. Optimising → **response surface** (2–4 factors, 3+ levels). Robustness → control factors crossed with noise factors.","DOE is **sequential**: screen, then characterise, then optimise. A DOE model is valid **only inside the region tested**. Always finish with **confirmation runs**. And the book warns: do not force a DOE if Measure and Analyze already gave the answer."],example:`**Service desk with 7 possible X’s.** Little is known, and each run is one pilot day.

- A full $2^7$ needs **128 runs**. Too costly.
- **Screening** first: a $2^{7-3}$ fraction needs only **16 runs**. It shows 3 X’s matter.
- **Characterise** the 3: a $2^3$ full factorial + 4 centre points = **12 runs**. Interactions are now clear.
- **Optimise** the 2 strongest with a response surface design, then run **confirmation runs** at the chosen settings.

**Spot the objective (wording):**
- "Which of these factors matter?" → **screening**.
- "Lowest possible handling time" → **optimising**.
- "Same response time whatever the call volume" → **robustness**.`,readIt:['"Many factors, little knowledge" → screening (fractional factorial) first.','"Best settings", "maximum", "minimum" → optimisation (response surface).','"Insensitive to", "consistent regardless of noise" → robustness.','"How big is each effect and do they interact?" → characterisation (full factorial).'],remember:["DOE sets X’s on purpose → cause and effect + interactions.","Objectives: screening, characterising, optimising, robustness (plus problem solving).","Book: fractional 4–15 factors · full 2–5 · RSM 2–4.","RSM is the design with the fewest factors.","Sequential: screen → characterise → optimise → confirm.","The model is valid only inside the tested region."],traps:["Starting with a full factorial or RSM when there are many factors — screen first.","Regression on historical data is not an experiment and cannot prove cause.",'Robustness ("insensitive to noise") is not the same as optimisation ("best value").',"Confirmation runs verify the predicted result; they do not estimate new effects."],video:[{kind:"title",say:"Why run an experiment? Four objectives, four kinds of design.",title:"Experiment Objectives",sub:"What a DOE is for"},{kind:"compare",say:"Regression on old data shows association. A designed experiment sets the X’s on purpose, so it shows cause and effect.",title:"Observe vs experiment",left:{head:"Historical data",points:["X’s change by chance","Association only","Interactions hard to see"]},right:{head:"Designed experiment",points:["X’s set on purpose","Cause and effect","Interactions estimated"]}},{kind:"bullets",say:"Screening finds the vital few, and characterising measures their effects. Optimising finds the best settings, and robustness makes Y insensitive to noise.",title:"Four objectives",bullets:["Screening: which X’s matter?","Characterising: how big? interactions?","Optimising: best settings for Y","Robustness: insensitive to noise"]},{kind:"steps",say:"Experiments run in sequence. Screen many factors cheaply, characterise the few, optimise, then confirm.",title:"The DOE sequence",steps:["Screen: fractional factorial (4–15 X’s)","Characterise: full factorial (2–5 X’s)","Optimise: response surface (2–4 X’s)","Confirm: confirmation runs"]},{kind:"decision",say:"First question: do you have many candidate factors and little knowledge? Then screen first with a fractional factorial.",title:"Where to start?",question:"Many candidate X’s and little process knowledge?",yes:"Screening: fractional factorial",no:"Few X’s: full factorial or RSM"},{kind:"callout",say:"Remember: seven factors in full is 128 runs. A screening fraction can do it in 16.",big:"Screen → characterise → optimise → confirm",small:"2⁷ = 128 runs · 2⁷⁻³ = 16 runs"}]},{topic:"4.3.2",title:"Experimental Methods",oneLine:"Trial and error and one-factor-at-a-time (OFAT) miss interactions and waste runs; a designed factorial experiment changes factors together in a balanced plan and sees everything.",explain:["**Trial and error** changes whatever looks promising until something works. No plan, no error estimate, and you cannot explain why it worked.",'**OFAT (one factor at a time)** changes one X while the others stay fixed, then moves to the next X. The book says OFAT is an **experimental style, not a DOE**. You "pick the winner" of the few combinations tested.',"OFAT’s **primary weakness**: it **cannot detect interactions**. Each OFAT effect is true **only at the fixed levels** of the other factors. When factors interact, OFAT can stop far from the true optimum (the book’s yield example stops at 92%).","A **designed (factorial) experiment** changes several X’s **together** in a **balanced, orthogonal** pattern. Every run is used for every effect (**hidden replication**), so it is more **efficient**, and it estimates **interactions** directly.","Precision: in a factorial with N runs, SD(effect) = 2σ/√N. For three factors, OFAT needs about **16 runs** to match the precision of an **8-run** $2^3$, and it still has no interaction estimate."],example:`**Login latency load test (ms).** A = cache TTL (30 / 300 s), B = database pool (20 / 60), C = compression.

**OFAT path:** start 377 ms → change A → 267 → change B (A kept high) → 255 → change C → 255.
OFAT says: "B saves only 12 ms, C does nothing."

**Factorial ($2^3$, 8 runs):** B effect = **−40 ms**, and an **AB interaction = +30 ms**.
- With a small pool (20): cache cuts latency from 375 → 265 ms (−110).
- With a big pool (60): cache cuts it from 305 → 255 ms (−50).

The pool matters a lot when the cache is short (−64 ms at A low). OFAT only tested B at A high, so it missed this.`,readIt:["Non-parallel lines on an interaction plot → interaction → OFAT would be misleading.",'An OFAT result "X does not matter" → ask: at what levels of the other X’s?','"Most efficient way to estimate several effects" → factorial design.','"Primary weakness of OFAT" → cannot detect interactions.'],remember:["OFAT = experimental style, not a DOE.","OFAT cannot detect interactions (primary weakness).","OFAT effects hold only at the fixed levels of the other X’s.","Factorial: every run used for every effect (hidden replication).","SD(effect) = 2σ/√N in a 2-level factorial.","OFAT can stop short of the true optimum."],traps:['"OFAT is a type of designed experiment" — false.',"Inefficiency is a weakness of OFAT, but the PRIMARY weakness is missing interactions.","Changing two things at once is bad only when unplanned; in an orthogonal design it is the point.","Reading an OFAT effect as a general effect of that factor."],video:[{kind:"title",say:"Three ways to try things: trial and error, one factor at a time, and a designed experiment.",title:"Experimental Methods",sub:"Trial & error vs OFAT vs DOE"},{kind:"compare",say:"One factor at a time looks careful, but it never sees two factors working together. A factorial design does.",title:"OFAT vs factorial",left:{head:"OFAT",points:["Change one X, hold the rest","No interactions","Effects only at fixed levels","Many runs, low precision"]},right:{head:"Factorial DOE",points:["Change X’s together, planned","Interactions estimated","Effects averaged over others","Every run used for every effect"]}},{kind:"figure",say:"Here is the load test. The cache helps much more when the database pool is small. The lines are not parallel: that is an interaction.",title:"The interaction OFAT missed",figure:{kind:"lines",title:"Interaction Plot for p95 Latency",xLabels:["Cache TTL 30 s (−)","Cache TTL 300 s (+)"],series:[{name:"DB pool 20 (B−)",values:[375,265]},{name:"DB pool 60 (B+)",values:[305,255]}],yLabel:"Mean latency (ms)",xLabel:"Cache TTL"},callouts:["Pool 20: cache saves 110 ms","Pool 60: cache saves 50 ms","Non-parallel → AB interaction = +30"]},{kind:"bullets",say:"OFAT tested the pool only with the long cache, and saw just 12 milliseconds. The factorial shows the pool effect is 40 milliseconds on average.",title:"What OFAT reported",bullets:["OFAT: pool saves 12 ms (at A high only)","At A low the pool saves 64 ms","Factorial average effect: −40 ms","Lesson: OFAT effects are conditional"]},{kind:"formula",say:"In a two-level factorial, every run counts for every effect. The effect’s standard deviation is two sigma over root N.",title:"Hidden replication",name:"SD(effect)",num:"2σ",den:"√N",note:"8-run $2^3$ matches about 16 OFAT runs, and still estimates interactions"},{kind:"callout",say:"Remember: the primary weakness of one factor at a time is that it cannot see interactions.",big:"OFAT cannot detect interactions",small:"OFAT is a style, not a DOE"}]},{topic:"4.3.3",title:"Experiment Design Considerations",oneLine:"A good experiment starts from a clear problem, a measurable response and sensible factor levels, and uses randomisation, replication, blocking and centre points to protect the result.",explain:["The book’s **11-step DOE method**: 1 Define the practical problem · 2 Establish the objective · 3 Select the output (response) · 4 Select the inputs (factors) · 5 Choose the levels · 6 Select the design · 7 Run the experiment and collect data · 8 Analyse and draw statistical conclusions · 9 Draw practical solutions · 10 Replicate or validate · 11 **Implement**.","**Response:** continuous if possible, and measured with a **good measurement system** (do the MSA first). Big measurement error hides real effects. **Factors:** controllable X’s. Hold the others **constant**, and list the **noise** you cannot control.","**Levels:** bold but realistic. Too **close** → the effect is lost in the noise. Too **wide** → you may jump over a peak or valley (curvature), or break the process. Use **centre points** to check for curvature.","Three protections. **Randomise** the run order → guards against time-related lurking variables (drift, learning). **Replicate** (reset and rerun each setting) → estimates pure error and gives power. **Block** a known nuisance (day, shift, site) → removes its effect from the error.","Count the runs: **runs = replicates × 2^k + centre points**. Plan the practical side: tell the **process owners** in advance, keep a **log book** of anything unusual, and have team members present."],example:`**Plan: fibre install time experiment.**

- **Problem:** installs take 6.2 h on average; target 5 h.
- **Response:** install time (h), from the work-order system (MSA done: timestamps validated).
- **Factors and levels:** A crew size 2 / 3 · B pre-survey no / yes · C kit pre-picked no / yes.
- **Held constant:** route type, region. **Noise:** weather → recorded in the log book.
- **Design:** $2^3$ with **2 replicates** = 2 × 8 = **16 runs**, randomised, **blocked by week** (2 weeks).

**Run count drill:** $2^3$, 1 replicate, 5 centre points → 8 + 5 = **13 runs** (the book’s answer). $2^4$ with 2 replicates → **32 runs**.

**Replicate or repeat?** Three readings from one setup = **repeats** (not independent). Resetting the setting and running again = a **replicate**.`,readIt:['"Effects not significant" — reasons: too few replicates, levels too close, levels too wide (missed a peak), or measurement error too large.',"Run order drawn at random → randomisation (protects against drift).","Same setting reset and run again → replication (estimates pure error).","Nuisance like day or shift handled as a separate factor → blocking."],remember:["11 steps: first = define the practical problem; last = implement solutions.","Runs = replicates × 2^k + centre points ($2^3$ + 5 CP = 13).","Randomise → protects against lurking time variables.","Replicate → pure error and power; repeat ≠ replicate.","Block → removes a known nuisance (day, shift, site).","MSA on the response before the experiment."],traps:["Repeated readings on one setup are not replicates.","Levels set very wide can jump over a maximum and show little change.","Blocking is for known nuisance variables; randomisation is for unknown ones.","Experiments are not only for manufacturing; transactional processes use them too."],video:[{kind:"title",say:"Plan the experiment well, or the data will not answer your question.",title:"Design Considerations",sub:"Plan before you run"},{kind:"steps",say:"The book’s eleven steps, in short. Problem, objective, response and factors, levels and design, then run, analyse, confirm and implement.",title:"The 11-step method (short)",steps:["1–2 Problem and objective","3–5 Response, factors, levels","6–7 Design, run, collect","8–9 Analyse, practical solution","10–11 Validate, implement"]},{kind:"bullets",say:"Randomise against unknown drift, and replicate to measure pure error. Block a known nuisance, like the day or the shift.",title:"Three protections",bullets:["Randomise: order drawn at random","Replicate: reset and rerun each setting","Block: day, shift or site as a block","Centre points: check curvature"]},{kind:"compare",say:"Choose levels with care. Too close and the effect hides in the noise. Too wide and you may jump right over the peak.",title:"Setting the levels",left:{head:"Too close",points:["Effect smaller than noise","Nothing looks significant"]},right:{head:"Too wide",points:["May jump over a peak","May break the process","Add centre points"]}},{kind:"callout",say:"Count the runs. Replicates times two to the k, plus centre points. Two cubed with five centre points is thirteen runs.",big:"Runs = replicates × 2^k + centre points",small:"2³ + 5 CP = 13 · 2⁴ × 2 replicates = 32"},{kind:"callout",say:"Remember: randomise for the unknown, block the known, and replicate to measure error.",big:"Randomise · Replicate · Block",small:"Step 1 = define the problem · step 11 = implement"}]},{topic:"4.4.1",title:"2^k Full Factorial Designs",oneLine:"A 2^k full factorial tests every combination of k factors at two levels; an effect is the average Y at the high level minus the average Y at the low level.",explain:["A **2^k full factorial** runs **every combination** of k factors, each at **2 levels**. Runs = 2^k: $2^2$ = 4, $2^3$ = 8, $2^4$ = 16, $2^5$ = 32. Factors can be numbers (4 h / 12 h) or categories (old / new script).","Levels are **coded**: low = **−1**, high = **+1**. In **standard order** the first column alternates − + − +, the second goes − − + +, the third four − then four +. The pattern doubles each time. Then **randomise** the run order before you run.","The **main effect** of a factor: $$\\text{Effect}=\\bar{y}_{+}-\\bar{y}_{-}$$ the average at high minus the average at low. Each average uses half the runs (4 of 8 in a $2^3$). The **main effects plot** shows these two averages; the **steeper** the line, the bigger the effect.","An **interaction** means the effect of one factor depends on the level of another. On an **interaction plot** the lines are **not parallel**. They do **not** have to cross. Parallel lines = no interaction.","Interaction effect AB: multiply the A and B columns to get the AB column, then use the same rule: average where AB = + minus average where AB = −. A $2^3$ estimates 3 main effects, 3 two-factor interactions and 1 three-factor interaction: **7 effects from 8 runs**."],example:`**Contact-centre AHT (minutes), $2^3$.** A = training (4 / 12 h), B = coaching (1 / 3 per month), C = agents per team lead (8 / 14).

| Run | A | B | C | AHT |
|---|---|---|---|---|
| 1 | − | − | − | 9.2 |
| 2 | + | − | − | 7.6 |
| 3 | − | + | − | 8.0 |
| 4 | + | + | − | 7.6 |
| 5 | − | − | + | 8.9 |
| 6 | + | − | + | 7.5 |
| 7 | − | + | + | 7.9 |
| 8 | + | + | + | 7.3 |

**Effect of A** = (7.6 + 7.6 + 7.5 + 7.3)/4 − (9.2 + 8.0 + 8.9 + 7.9)/4 = 7.5 − 8.5 = **−1.0 min**.
B = 7.7 − 8.3 = **−0.6**. C = 7.9 − 8.1 = **−0.2**. **AB = +0.5** (all others ≈ 0).

Training cuts 1.5 min when coaching is low, but only 0.5 min when coaching is high.`,readIt:["Main effects plot: steepest line = largest effect; flat line = little effect.","Line goes down from − to + → raising the factor lowers Y (negative effect).","Interaction plot: non-parallel lines → interaction; parallel → none.","Count runs: 2^k (times replicates, plus centre points)."],remember:["Runs = 2^k: 4, 8, 16, 32 for k = 2, 3, 4, 5.","Coded levels: −1 low, +1 high.","Effect = ȳ(+) − ȳ(−).","Interaction = non-parallel lines (crossing not needed).","A $2^3$ has 7 effects: A, B, C, AB, AC, BC, ABC.","Standard order doubles the pattern; run in random order."],traps:["Lines do not have to cross for an interaction; non-parallel is enough.","A $2^4$ has 16 runs, not 8 (2 × 4) — use powers, not products.","The effect is not the difference between single runs; it uses the averages of half the runs each.","Standard order is for writing the design; the experiment should be run in random order."],video:[{kind:"title",say:"The two to the k full factorial: every combination, two levels each.",title:"2^k Full Factorial",sub:"Every combination at two levels"},{kind:"bullets",say:"k factors at two levels need two to the k runs. Three factors need eight runs. Four need sixteen.",title:"How many runs?",bullets:["2² = 4 runs","2³ = 8 runs","2⁴ = 16 runs · 2⁵ = 32 runs","Code levels −1 (low) and +1 (high)"]},{kind:"bullets",say:"A main effect is the average at the high level minus the average at the low level. For training: 7.5 minus 8.5 is minus one minute.",title:"Main effect",bullets:["Effect = average Y at + minus average Y at −","Each average uses half the runs (4 of 8)","Training: 7.5 − 8.5 = −1.0 min","Negative effect: raising the factor lowers Y"]},{kind:"figure",say:"The main effects plot shows the two averages for each factor. Training has the steepest line, so the biggest effect.",title:"Main effects plot",figure:{kind:"lines",title:"Main Effects Plot for AHT (data means)",xLabels:["Low (−1)","High (+1)"],series:[{name:"A Training",values:[8.5,7.5]},{name:"B Coaching",values:[8.3,7.7]},{name:"C Team size",values:[8.1,7.9]}],yLabel:"Mean AHT (min)"},callouts:["A: −1.0 min (steepest)","B: −0.6 min","C: −0.2 min (almost flat)"]},{kind:"figure",say:"Now the interaction plot. Training saves 1.5 minutes when coaching is low, but only half a minute when coaching is high. The lines are not parallel.",title:"Interaction plot",figure:{kind:"lines",title:"Interaction Plot for AHT (data means)",xLabels:["Training 4 h (−)","Training 12 h (+)"],series:[{name:"Coaching 1/month (B−)",values:[9.05,7.55]},{name:"Coaching 3/month (B+)",values:[7.95,7.45]}],yLabel:"Mean AHT (min)",xLabel:"Training"},callouts:["B low: 9.05 → 7.55 (−1.5)","B high: 7.95 → 7.45 (−0.5)","Non-parallel → AB = +0.5"]},{kind:"callout",say:"Remember: effect equals high average minus low average, and non-parallel lines mean an interaction.",big:"Effect = ȳ(+) − ȳ(−)",small:"Non-parallel lines = interaction"}]},{topic:"4.4.2",title:"Linear & Quadratic Mathematical Models",oneLine:"A 2-level factorial gives a linear model with interaction terms (coefficient = effect ÷ 2); a quadratic model with squared terms needs at least three levels per factor.",explain:["A DOE ends with a **prediction equation**, Y = f(X). In **coded units** (−1 / +1) the 2-level model is $$\\hat{Y}=b_0+b_1A+b_2B+b_{12}AB$$ **b₀** = the grand mean. Each **coefficient = effect ÷ 2**, because coded X moves 2 units from −1 to +1.","This is the **linear** (first-order) model. The **AB** term lets the surface **twist**, but each factor alone still acts as a **straight line**. Coded coefficients can be compared directly: the biggest |coefficient| = the biggest effect.","Keep only the important terms. **Hierarchy:** if AB stays in the model, A and B stay too. Minitab gives the equation in **coded** units (easy to compare) and **uncoded** units (real settings).","A 2-level design only sees the **two ends** of each factor. It cannot see a bend in the middle. To model a curve you need a **quadratic** model: $$\\hat{Y}=b_0+b_1A+b_2B+b_{12}AB+b_{11}A^2+b_{22}B^2$$ with **3 or more levels** per factor.","Quadratic models come from **response surface designs** (central composite or Box-Behnken). Centre points can **detect** curvature, but cannot say which factor caused it. A full quadratic in k factors has 1 + 2k + k(k−1)/2 terms (6 for k = 2)."],example:`**AHT model (coded), from the $2^3$:** grand mean 8.0; effects A −1.0, B −0.6, AB +0.5.

$$\\hat{Y}=8.00-0.50A-0.30B+0.25AB$$

**Predict A = +1, B = +1:** 8.00 − 0.50 − 0.30 + 0.25 = **7.45 min**. The two runs at that setting gave 7.6 and 7.3 → average 7.45. ✓

**Predict A = +1, B = −1:** 8.00 − 0.50 + 0.30 − 0.25 = **7.55 min**.

**Quadratic example.** CSAT vs call-script length at 2, 4 and 6 min (3 calls each):
- Linear fit: R² = **9.3%** (it sees almost no trend).
- Quadratic: Ŷ = 3.467 + 2.408X − 0.2875X², R² = **96.3%**, peak at **4.2 min** (CSAT 8.5).`,readIt:["Coded coefficient = effect ÷ 2; constant = grand mean.","Largest |coded coefficient| = most important factor.","Interaction term in the model → keep its main effects (hierarchy).","Need a curve (peak or valley)? → quadratic model → 3+ levels (RSM)."],remember:["Linear model: Ŷ = b₀ + b₁A + b₂B + b₁₂AB.","Coefficient = effect ÷ 2 (coded units).","b₀ = grand mean of all runs.","Quadratic adds A², B²: needs ≥ 3 levels.","Centre points detect curvature; RSM models it.","Hierarchy: keep A and B when AB is in."],traps:["Using the effect as the coefficient — the coefficient is half the effect.","A 2-level design cannot estimate squared terms.","Comparing uncoded coefficients to rank factors — units differ; use coded ones.","Centre points tell you curvature exists, not which factor causes it."],video:[{kind:"title",say:"From effects to an equation: linear and quadratic models.",title:"Linear & Quadratic Models",sub:"Y = f(X) from a DOE"},{kind:"formula",say:"In coded units, each coefficient is half the effect. The factor moves two units, from minus one to plus one.",title:"Effect to coefficient",name:"Coefficient",num:"Effect",den:"2",note:"A: −1.0 ÷ 2 = −0.50 · constant = grand mean 8.00"},{kind:"bullets",say:"Here is the AHT model. Put in plus one or minus one for each factor to predict.",title:"The AHT model",bullets:["Ŷ = 8.00 − 0.50A − 0.30B + 0.25AB","A+, B+: 8.00 − 0.50 − 0.30 + 0.25 = 7.45","Matches the two runs (7.6, 7.3)","Hierarchy: AB in → keep A and B"]},{kind:"figure",say:"Two levels see only the ends. Here CSAT peaks in the middle. A straight line explains nine percent; the quadratic explains ninety-six.",title:"When a line is not enough",figure:{kind:"scatter",title:"CSAT vs Script Length (quadratic fit)",points:[[2,7.1],[2,7.3],[2,7],[4,8.4],[4,8.6],[4,8.5],[6,7.6],[6,7.4],[6,7.7]],xLabel:"Script length (min)",yLabel:"CSAT score",fit:{b0:3.4667,b1:2.4083,b2:-.2875},stats:[["R-Sq linear","9.3%"],["R-Sq quad","96.3%"],["Peak","4.2 min"]]},callouts:["Three levels: 2, 4, 6 min","Linear R² 9.3% → misses the peak","Quadratic R² 96.3%, peak ≈ 4.2 min"]},{kind:"compare",say:"Linear models come from two-level designs. Quadratic models need three or more levels, from response surface designs.",title:"Linear vs quadratic",left:{head:"Linear (+ interaction)",points:["2 levels per factor","Full or fractional factorial","Straight lines, can twist"]},right:{head:"Quadratic",points:["3+ levels per factor","Response surface (CCD, Box-Behnken)","Finds a peak or valley"]}},{kind:"callout",say:"Remember: coded coefficient equals half the effect, and squared terms need three levels.",big:"Coefficient = Effect ÷ 2",small:"Quadratic needs ≥ 3 levels"}]},{topic:"4.4.3",title:"Balanced & Orthogonal Designs",oneLine:"Balanced means each level appears equally often; orthogonal means the columns are independent, so every effect can be estimated separately.",explain:["A **balanced** design has each level of each factor appear the **same number of times**. In coded units, **every column sums to zero** (four −1 and four +1 in a $2^3$).","An **orthogonal** design has **no correlation between columns**. Multiply any two columns row by row and add: the **sum is zero**. This is true for main-effect columns and interaction columns.","Why it matters: in an orthogonal design each effect is estimated **independently** of the others. The estimate for A does not change when you add or remove B from the model. That is why DOE beats regression on messy historical data, where X’s overlap (multicollinearity).","The book: a design **cannot be orthogonal if it is not balanced**. A design **can be balanced but not orthogonal**. Use designs that are both.","Full and fractional **2-level factorials are balanced and orthogonal** by construction. **Lose or spoil one run** and you lose both, and the effects become correlated. So protect every run, and re-run a failed one if you can."],example:`**Check a $2^2$ design (coded).**

| Run | A | B | A × B |
|---|---|---|---|
| 1 | −1 | −1 | +1 |
| 2 | +1 | −1 | −1 |
| 3 | −1 | +1 | −1 |
| 4 | +1 | +1 | +1 |

- **Balanced:** sum of A = −1 + 1 − 1 + 1 = **0**. Same for B.
- **Orthogonal:** sum of A × B = +1 − 1 − 1 + 1 = **0**.

**Now lose run 4** (the system crashed that day):
- Sum of A = −1 + 1 − 1 = **−1** → not balanced.
- Sum of A × B = +1 − 1 − 1 = **−1** → not orthogonal. A and B now overlap.`,readIt:["Column sum = 0 → balanced.","Sum of products of two columns = 0 → orthogonal.","A missing or spoiled run → the design is no longer balanced or orthogonal.","Orthogonal → effects independent; adding or dropping terms does not change the others."],remember:["Balanced: each level appears equally often; column sum = 0.","Orthogonal: sum of products of any two columns = 0.","Cannot be orthogonal without being balanced.","Can be balanced but not orthogonal.","2-level full and fractional factorials are both.","Orthogonal → independent effect estimates."],traps:['"Balanced means orthogonal" — false; balanced is needed but not enough.','"An orthogonal design can be unbalanced" — false (book).',"Losing one run is not harmless: it breaks balance and orthogonality.","Orthogonality is between columns (factors), not between runs."],video:[{kind:"title",say:"Balanced and orthogonal: the two properties that make a DOE so powerful.",title:"Balanced & Orthogonal",sub:"Clean, independent effects"},{kind:"compare",say:"Balanced means each level shows up the same number of times. Orthogonal means the columns do not overlap at all.",title:"Two properties",left:{head:"Balanced",points:["Each level equally often","Column sum = 0","e.g. four −1, four +1"]},right:{head:"Orthogonal",points:["Columns independent","Σ (column × column) = 0","Effects estimated separately"]}},{kind:"steps",say:"In a 2² design, A, B and A × B each sum to zero. So the design is balanced and orthogonal.",title:"Check a 2² design",steps:["A: −1 +1 −1 +1 → sum 0","B: −1 −1 +1 +1 → sum 0","A×B: +1 −1 −1 +1 → sum 0","Balanced ✓ Orthogonal ✓"]},{kind:"decision",say:"The book rule: is the design balanced? If not, it cannot be orthogonal. If it is, check the column products too.",title:"Book rule",question:"Is the design balanced?",yes:"Maybe orthogonal: check Σ products = 0",no:"Cannot be orthogonal"},{kind:"bullets",say:"Lose run four, and A sums to minus one, and A times B sums to minus one. Now A and B overlap.",title:"Lose one run",bullets:["Run 4 lost (system crash)","Sum A = −1 → not balanced","Sum A×B = −1 → not orthogonal","Protect every run; re-run if you can"]},{kind:"callout",say:"Remember: orthogonal needs balanced, but balanced does not guarantee orthogonal.",big:"Orthogonal ⇒ balanced, not the reverse",small:"Column sum 0 · product sum 0"}]},{topic:"4.4.4",title:"Model Fit & Diagnosis, Center Points",oneLine:"Judge a DOE model with effect p-values, R², adjusted R² and residual plots, then use centre points to test whether a straight-line model misses curvature.",explain:["**Which effects are real?** Use the **p-values** (or the **Pareto chart of standardised effects**: bars past the reference line are significant). With no replicates there is no error estimate, so use a **normal plot of effects** (real effects fall off the line) or add replicates or centre points.","**Reduce the model:** remove non-significant terms, **highest-order first** (three-way, then two-way), and respect **hierarchy**. Then check **R²**, **R²(adj)** and **S**. A big gap between R² and adj R² means useless terms.","**Diagnose** with the same **residual plots** as regression: normal plot, versus fits, versus order. Patterns mean the model or the assumptions are wrong.","**Centre points** are runs with every factor at its **middle level (0)**. They (1) **test for curvature**, (2) give a **pure error** estimate without replicating the corners, and (3) check the process stayed **stable** during the experiment. They only work for **numeric** factors.","**Curvature test:** compare the **mean of the centre points** with the **mean of the corner (factorial) points**. If they differ significantly (Minitab’s **Ct Pt** p-value < α), the linear model misses a bend. Next step: a **response surface** design to model it."],example:`**AHT $2^3$ + 4 centre points** (8 h training, 2 coaching sessions, 11 agents per lead): 8.5, 8.7, 8.4, 8.6 min.

- Mean of the 8 corner runs = **8.00**. Mean of the centre points = **8.55**.
- Curvature = 8.55 − 8.00 = **0.55 min**. Pure error s = 0.129 (from the centre points, df = 3).
- $$t=\\dfrac{0.55}{0.129\\sqrt{\\tfrac18+\\tfrac14}}=6.96,\\quad p=0.006$$

**Ct Pt p = 0.006 < 0.05 → significant curvature.** A straight-line model would predict 8.00 at the centre; the process actually gives 8.55. Total runs: 8 + 4 = **12**. Next: a response surface design.

**No significant effects at all?** The book’s reasons: too few replicates, levels too close, levels too wide (missed a peak), or measurement error too large.`,readIt:["Pareto of standardised effects: bars beyond the reference line = significant.","Normal plot of effects: points far off the line = real effects.","Ct Pt p-value < α → significant curvature → consider RSM.","Ct Pt p-value > α → linear model is adequate in this region."],remember:["Remove non-significant terms highest-order first; keep hierarchy.","Centre point = all factors at their middle (0) level.","Centre points: curvature test + pure error + stability check.","Curvature = centre mean vs corner mean (Ct Pt p-value).","Centre points need numeric factors.","Curvature found → response surface next."],traps:["Centre points detect curvature but cannot tell which factor is curved.","Adding centre points increases the run count (8 + 4 = 12).","Centre points are not only for optimisation; they also give pure error and a stability check.","Drop the three-way interaction before its two-way and main effects, never the reverse."],video:[{kind:"title",say:"Is the model any good? And is the world really straight between the corners?",title:"Model Fit & Centre Points",sub:"Diagnose, then test for curvature"},{kind:"steps",say:"Judge the model in four steps. Find the significant effects, reduce the model, read the fit numbers, then check the residuals.",title:"Judge the model",steps:["p-values / Pareto of effects","Drop highest-order terms first","R², adj R², S","Residual plots"]},{kind:"bullets",say:"Centre points sit in the middle of every factor. They do three jobs.",title:"What centre points do",bullets:["Test for curvature","Give pure error without full replicates","Check stability during the experiment","Numeric factors only"]},{kind:"figure",say:"A straight line through the corners predicts 8.0 at the centre. The centre points average 8.55. The middle bulges: that is curvature.",title:"Centre points reveal a bend",figure:{kind:"lines",title:"Corners vs Centre Points (AHT)",xLabels:["Low (−1)","Centre (0)","High (+1)"],series:[{name:"Straight-line model",values:[8.5,8,7.5]},{name:"Observed means",values:[8.5,8.55,7.5]}],yLabel:"Mean AHT (min)",xLabel:"Training (coded)"},callouts:["Corner mean = 8.00","Centre mean = 8.55","Ct Pt p = 0.006 → curvature"]},{kind:"decision",say:"Read the centre point p-value. Below alpha means curvature: move to a response surface design. Above alpha: the linear model is fine here.",title:"Curvature?",question:"Is the Ct Pt p-value below α?",yes:"Curvature → response surface design",no:"Linear model is adequate here"},{kind:"callout",say:"Remember: centre points detect curvature, but they cannot tell you which factor bends.",big:"Centre mean ≠ corner mean → curvature",small:"Then use a response surface design"}]},{topic:"4.5.1",title:"Fractional Factorial Designs",oneLine:"A 2^(k−p) fractional factorial runs a half, quarter or smaller fraction of the full design to screen many factors cheaply, at the price of aliased effects.",explain:["A full factorial doubles with each factor: 5 factors = 32 runs, 7 = 128, 10 = 1,024. A **fractional factorial** runs only a **fraction**.","Notation **2^(k−p)**: **k** factors, **p** generators, **2^(k−p) runs**, a **1/2^p fraction**. $2^{6-2}$ = 6 factors, 2⁴ = **16 runs**, a **quarter** fraction. Always work out the exponent first.","How it is built: write a full factorial in **k − p** factors, then make each extra factor from an interaction column, a **generator**, e.g. **D = ABC**. Multiply the signs: run (+, −, −) → D = (+)(−)(−) = +. The new column stays balanced and orthogonal.",'Why it works: **sparsity of effects**. Only a few effects are big, and high-order interactions are usually negligible. So their columns can be "spent" on extra factors.',"The price: **aliasing**. Each column estimates an effect **plus its aliases**. Fractions are for **screening**; characterise the vital few afterwards. A **fold-over** (rerun with all signs reversed) can separate aliased effects."],example:`**Service-desk MTTR screening, $2^{4-1}$, D = ABC (8 pilot days instead of 16).**
A auto-triage · B ticket template · C AI knowledge articles · D swarming.

Results (h): 6.8, 4.6, 6.4, 4.4, 5.6, 4.0, 5.4, 3.6.

**Effect of A** = (4.6 + 4.4 + 4.0 + 3.6)/4 − (6.8 + 6.4 + 5.6 + 5.4)/4 = 4.15 − 6.05 = **−1.90 h**.

All effects: A **−1.90**, B −0.30, C **−0.90**, D −0.10, AB+CD 0.00, AC+BD +0.20, AD+BC 0.00.

A and C are the vital few. Next: a full factorial in A and C, then confirmation runs.

**Run-count drill:** $2^{5-1}$ = 16 · $2^{6-2}$ = 16 · $2^{7-4}$ = 8 · $2^{8-4}$ = 16.`,readIt:["Read 2^(k−p): runs = 2 to the power (k − p); fraction = 1/2^p.","Generator D = ABC: the D column is the product of A, B and C signs.","Large bars on the effects chart = the vital few to study next.","Each column = effect + aliases; check the alias table before concluding."],remember:["2^(k−p): k factors, p generators, 2^(k−p) runs.","Fraction = 1/2^p (p = 1 half, p = 2 quarter).","Generator e.g. D = ABC: multiply the signs.","Sparsity of effects justifies fractions.","Fractions are for screening.","Every fraction has some aliasing."],traps:["$2^{6-2}$ is 16 runs, not 64 or 4.","A $2^{5-2}$ is a quarter fraction, not a half.","With many factors, a full factorial or RSM is not the first design — screen first.","A fold-over adds runs to the original; it is not a brand-new experiment."],video:[{kind:"title",say:"Fractional factorials: screen many factors with a fraction of the runs.",title:"Fractional Factorials",sub:"2^(k−p) designs"},{kind:"bullets",say:"Read the notation. Two to the six minus two: six factors, two generators, two to the four is sixteen runs, a quarter fraction.",title:"Reading 2^(k−p)",bullets:["k = factors, p = generators","Runs = 2^(k−p)","Fraction = 1/2^p","2⁶⁻² → 16 runs, quarter fraction"]},{kind:"steps",say:"Build a half fraction of four factors. Write the full design in A, B and C. Then make D equal to A times B times C.",title:"Build a 2⁴⁻¹",steps:["Full 2³ in A, B, C (8 runs)","Generator: D = ABC","Run (+,−,−) → D = +","Still balanced and orthogonal"]},{kind:"figure",say:"Eight pilot days screened four factors. Auto-triage and AI knowledge articles have the biggest effects. They are the vital few.",title:"Screening result",figure:{kind:"bars",title:"Size of Effects on MTTR (|effect|, h)",categories:["A","B","C","D","AB+CD","AC+BD","AD+BC"],series:[{name:"|Effect| (h)",values:[1.9,.3,.9,.1,0,.2,0]}],yLabel:"|Effect| (h)"},callouts:["A (auto-triage): −1.90 h","C (AI articles): −0.90 h","Two-factor columns hold pairs"]},{kind:"compare",say:"The gain is fewer runs. The price is aliasing: some effects share a column.",title:"Gain and price",left:{head:"Gain",points:["8 runs instead of 16","Screen many factors fast","Sparsity of effects"]},right:{head:"Price",points:["Aliasing","AB is mixed with CD","Confirm with more runs"]}},{kind:"callout",say:"Remember: work out k minus p first, then two to that power.",big:"Runs = 2^(k−p) · fraction = 1/2^p",small:"Screen first, then characterise"}]},{topic:"4.5.2",title:"Confounding Effects",oneLine:"Confounded (aliased) effects share the same column of signs, so the experiment can only estimate their sum; you find the aliases by multiplying with the defining relation.",explain:["In a fraction, two effects can have **identical sign columns**. Then the design cannot tell them apart. They are **confounded**, also called **aliased**. The estimate is their **sum**.","Turn each generator into a **defining relation**: D = ABC → multiply both sides by D → **I = ABCD**. **I** is the identity column (all +).","To find an alias: **multiply the effect by the word** and cancel any **squared** letter (A² = I). A × ABCD = **BCD**, so A = BCD. AB × ABCD = **CD**, so AB = CD.","With **two or more generators**, include every **product** of the words. D = AB and E = AC give I = ABD = ACE = **BCDE** (ABD × ACE). Each column of a 2^(k−p) design carries **2^p effects**.","Living with aliases: use **sparsity** (high-order terms are usually zero) and **heredity** (an interaction usually involves factors with big main effects). To separate them, add runs (fold-over). **Blocking** deliberately confounds a nuisance (day, shift) with a high-order interaction such as ABC."],example:`**$2^{4-1}$, D = ABC → I = ABCD.**

| Effect | × ABCD | Alias |
|---|---|---|
| A | A²BCD | A = **BCD** |
| D | ABCD² | D = **ABC** |
| AB | A²B²CD | AB = **CD** |
| AC | A²BC²D | AC = **BD** |
| AD | A²BCD² | AD = **BC** |

In the MTTR screening the AC column gave +0.20. That is **AC + BD** together — we cannot say which one.

**Two generators:** $2^{5-2}$ with D = AB, E = AC → I = ABD = ACE = BCDE. A = BD = CE = ABCDE: **4 effects per column** (2² = 4).`,readIt:['Alias table "A + BCD" → the A estimate also contains BCD.',"To find an alias: effect × defining word, cancel squared letters.","Two generators → add the product word (generalised interaction).","Effects per column = 2^p."],remember:["Confounded = aliased = identical sign columns; only the sum is estimated.","Generator D = ABC → defining relation I = ABCD.","Alias = effect × word; squared letters cancel (A² = I).","I = ABCD: A = BCD, AB = CD.","Each column carries 2^p effects.","Blocking confounds a nuisance with a high-order interaction."],traps:["A × ABCD is BCD, not A²BCD — squared letters cancel.","AB is aliased with CD, not with D (D = ABC is the generator).","Forgetting the product word (BCDE) when there are two generators.","Blocking does not confound main effects with blocks; it uses a high-order interaction."],video:[{kind:"title",say:"Confounding: when two effects share one column.",title:"Confounding Effects",sub:"Aliases and the defining relation"},{kind:"compare",say:"In the half fraction, the AB column and the CD column are exactly the same. So the experiment only sees AB plus CD.",title:"Identical columns",left:{head:"AB column",points:["+ − − + + − − +","Looks like AB"]},right:{head:"CD column",points:["+ − − + + − − +","Same signs → aliased"]}},{kind:"steps",say:"Turn the generator D = ABC into I = ABCD. Multiply the effect by the word, then cancel any squared letters.",title:"Find an alias",steps:["D = ABC → I = ABCD","Multiply: AB × ABCD = A²B²CD","Cancel squares → AB = CD"]},{kind:"bullets",say:"Here is the full alias list for the half fraction with I equals A B C D.",title:"Aliases when I = ABCD",bullets:["A = BCD · B = ACD · C = ABD · D = ABC","AB = CD","AC = BD","AD = BC"]},{kind:"decision",say:"Is there more than one generator? Then multiply the words together and add the product to the defining relation.",title:"Two generators?",question:"More than one generator?",yes:"Add the products: I = ABD = ACE = BCDE",no:"One word: I = ABCD"},{kind:"callout",say:"Remember: alias equals effect times word, and squared letters cancel.",big:"Alias = effect × word (A² = I)",small:"Each column carries 2^p effects"}]},{topic:"4.5.3",title:"Experimental Resolution",oneLine:"Resolution is the length of the shortest word in the defining relation; III aliases main effects with two-factor interactions, IV keeps main effects clear, V keeps two-factor interactions clear too.",explain:["**Resolution** tells you how badly a fraction is confounded. It is the **length of the shortest word** in the defining relation, written in Roman numerals: $2^{4-1}_{IV}$.","**Resolution III:** main effects are aliased with **two-factor interactions** (2FIs). Fine for rough screening only. Example: $2^{3-1}$, I = ABC → A = BC.","**Resolution IV:** main effects are **clear** of 2FIs (aliased only with three-factor ones), but **2FIs are aliased with each other**. Example: $2^{4-1}$, I = ABCD → A = BCD, AB = CD.","**Resolution V:** main effects **and** 2FIs are clear of each other. 2FIs are aliased only with three-factor interactions. Example: $2^{5-1}$, I = ABCDE → AB = CDE. Rule: the orders of two aliased effects add up to at least the resolution (III: 1 + 2; IV: 1 + 3 or 2 + 2; V: 2 + 3).","Higher resolution = **more runs**. Choose the **fewest runs** that give the resolution your question needs. Always generate from the **highest-order** interaction: D = ABC gives IV, D = AB only III. **Do not use resolution III to optimise** a process."],example:`**Find the resolution.**

- $2^{4-1}$, D = ABC → I = ABCD → shortest word 4 letters → **IV**.
- $2^{4-1}$, D = AB → I = ABD → 3 letters → **III** (worse choice).
- $2^{5-2}$, D = AB, E = AC → I = ABD = ACE = BCDE → shortest = 3 → **III**.
- $2^{6-2}$, E = ABC, F = BCD → I = ABCE = BCDF = ADEF → all 4 → **IV**.
- $2^{5-1}$, E = ABCD → I = ABCDE → **V**.

**Design table (2–8 factors):** 8 runs: 4 factors IV, 5–7 factors III. 16 runs: 5 factors **V**, 6–8 factors IV. 32 runs: 6 factors VI, 7–8 IV.

**Fewest runs for resolution V:** 5 factors → 16 runs; 6 factors → 32 runs.`,readIt:["Find the shortest word in the defining relation (include product words) → that length = resolution.",'"Main effects clear, 2FIs aliased with each other" → resolution IV.','"Least resolution to estimate all 2FIs clear" → resolution V.',"Minitab’s design table: green = high resolution, red = resolution III (use with caution)."],remember:["Resolution = length of the shortest word in the defining relation.","III: main effects aliased with 2FIs.","IV: main effects clear; 2FIs aliased with 2FIs.","V: main effects and 2FIs clear.","Aliased orders add to ≥ resolution.","Generate from the highest-order interaction (D = ABC → IV)."],traps:["Taking the longest or the first word instead of the shortest.","Forgetting product words (e.g. BCDE) before finding the shortest.","32 runs do not always give resolution V; with 7–8 factors they give IV.","Resolution III is for screening, not for optimising."],video:[{kind:"title",say:"Resolution: how much a fraction mixes up its effects.",title:"Experimental Resolution",sub:"III, IV and V"},{kind:"callout",say:"Resolution is simply the length of the shortest word in the defining relation.",big:"Resolution = length of the shortest word",small:"I = ABCD → 4 letters → resolution IV"},{kind:"bullets",say:"Resolution III mixes main effects with two-factor interactions. IV keeps main effects clear but mixes 2FIs together. V keeps both clear.",title:"III, IV, V",bullets:["III: main = 2FI (A = BC)","IV: main clear; 2FI = 2FI (AB = CD)","V: main and 2FI clear (AB = CDE)","Orders add to ≥ resolution"]},{kind:"compare",say:"Same eight runs, two generators. D equals A B C gives resolution four. D equals A B gives only resolution three.",title:"Choose the generator",left:{head:"D = ABC",points:["I = ABCD","Shortest word 4","Resolution IV ✓"]},right:{head:"D = AB",points:["I = ABD","Shortest word 3","Resolution III ✗"]}},{kind:"steps",say:"To read a design: write the defining relation, add the product words, find the shortest word, then name the resolution.",title:"Find the resolution",steps:["Write I = generator words","Add all product words","Find the shortest word","Its length = resolution"]},{kind:"callout",say:"Remember: resolution five is the least resolution that keeps all two-factor interactions clear.",big:"III screen · IV mains clear · V 2FIs clear",small:"Resolution = shortest word length"}]},{topic:"improve-map",title:"Which Improve tool do I use?",oneLine:"Pick the tool by asking: historical data or a planned experiment, one X or many, straight or curved, and how many factors you need to test.",explain:["**Question 1 — historical data or a planned experiment?** If you can only **observe** the process (old data), use **correlation and regression**: association only. If you can **set the X’s on purpose**, run a **designed experiment (DOE)**: cause and effect and interactions.","**Regression path.** Strength only → **correlation** (r). One X, straight line → **simple linear regression**. One X, curve → **quadratic or cubic** (or transform). Several X’s → **multiple regression** (check VIF). Skewed Y or unequal spread → **Box-Cox** transformation.","**Predicting.** For the **average** Y at an X → **confidence interval**. For **one** new Y → **prediction interval**. Always check the **residuals** before you trust any of these.","**DOE path — how many factors?** Many (book: 4–15) and little knowledge → **fractional factorial** to screen (resolution III or IV). Few (2–5) → **full factorial**, with **centre points** to check curvature. Curvature found, 2–4 factors → **response surface** for the optimum.","**Need interactions clear?** Main effects only → resolution III/IV may do. All two-factor interactions → resolution **V** or a full factorial."],example:`**Quick practice (telecom).**

| Situation | Tool |
|---|---|
| How strongly do utilisation and latency move together? | **Correlation** |
| Predict install time from route length | **Simple regression** |
| Latency curves up as links fill | **Quadratic regression** |
| MTTR from backlog, staff and KB accuracy | **Multiple regression** |
| Promise one customer an install window | **Prediction interval** |
| Skewed ticket ages before capability | **Box-Cox** |
| 9 possible causes of repeat calls, little knowledge | **Fractional factorial** (screen) |
| 3 known drivers of AHT, interactions wanted | **Full factorial + centre points** |
| Centre points show curvature; find best settings | **Response surface** |`,readIt:["Old data only → regression (association). Set X’s on purpose → DOE (cause).","Several X’s → multiple regression; curve → quadratic or transform.","Average → CI; one unit → PI.","Many factors → fractional; few → full factorial; curvature → RSM."],remember:["Regression = association; DOE = cause and effect.","Curve → quadratic / cubic / transform.","CI = mean, PI = one value (wider).","Fractional 4–15 factors, full 2–5, RSM 2–4 (book).","Centre points → test curvature.","Resolution V or full factorial to see all 2FIs."],traps:["Using regression on historical data to claim cause — you need a DOE.","Starting with a full factorial when there are many candidate factors.","Using a resolution III design to optimise a process.","Using a CI when the question is about one new unit."],video:[{kind:"title",say:"Which Improve tool do I use? A few quick questions take you there.",title:"Which Improve tool?",sub:"Regression or DOE, and which one"},{kind:"decision",say:"Can you set the X’s on purpose? Then run a designed experiment. If you only have old data, use regression.",title:"Observe or experiment?",question:"Can you set the X’s on purpose?",yes:"Designed experiment (cause and effect)",no:"Correlation / regression (association)"},{kind:"steps",say:"One X and a straight line → simple regression; a curve → add X². Several X’s → multiple regression; skewed Y → Box-Cox.",title:"Regression path",steps:["One X, straight → simple regression","Curve → quadratic / cubic","Several X’s → multiple regression","Skewed Y → Box-Cox"]},{kind:"decision",say:"Predicting? For the average, use the confidence interval. For one new unit, use the wider prediction interval.",title:"Which interval?",question:"Is the question about ONE new unit?",yes:"Prediction interval",no:"Confidence interval (mean)"},{kind:"steps",say:"On the DOE path, count the factors: many → screen with a fraction; few → full factorial with centre points. Curvature → response surface.",title:"DOE path",steps:["4–15 factors → fractional (screen)","2–5 factors → full factorial + centre points","Curvature → response surface (2–4)","Confirm the best settings"]},{kind:"decision",say:"Do you need all two-factor interactions clear? Then use resolution five or a full factorial.",title:"Interactions clear?",question:"Must all two-factor interactions be clear?",yes:"Resolution V or full factorial",no:"Resolution III / IV for screening"},{kind:"callout",say:"Remember the map. Observe or experiment, then the number of X’s, then the shape.",big:"Old data → regression · set X’s → DOE",small:"Many factors → fraction · few → full · curve → RSM"}]}],s=["4.1.1","4.1.2","4.1.3","4.2.1","4.2.2","4.2.3","4.2.4","4.2.5","4.3.1","4.3.2","4.3.3","4.4.1","4.4.2","4.4.3","4.4.4","4.5.1","4.5.2","4.5.3","improve-map"],n=[...T,...B].sort((e,t)=>s.indexOf(e.topic)-s.indexOf(t.topic));Object.fromEntries(n.map(e=>[e.topic,e]));const x={phase:"Improve",lessons:n,base:"/improve-coach",videoDir:"",storeKey:"svbb-coach-improve",mapTopic:"improve-map",mapSection:"4.2",mapPool:e=>e.phase===4&&(e.qtype==="best-action"||e.qtype==="scenario"),theme:{text:"text-amber",bg:"bg-amber",soft:"bg-amber/10",softer:"bg-amber/5"}};function P(){return i.jsx(o,{cfg:x})}export{P as default};
